1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	};
37	
38	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
39	
40	const quoteFor = (items: Item[]): Result => {
41	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
42	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
43	  return {
44	    premium: policyBase + firstInsuranceSurcharge + PROCESSING_FEE,
45	  };
46	};
47	
48	const resultFor = (step: Step): Result => {
49	  if (step.op === "quote") return quoteFor(step.items);
50	  throw new Error(`unsupported step: ${step.op}`);
51	};
52	
53	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
54	  results: scenario.steps.map(resultFor),
55	});
56

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Simplest case
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	
15	  // Base premiums per item type (with first insurance surcharge + fee)
16	  it("a single sword → base premium 100 G", () => {
17	    const result = runScenario({
18	      customer: { yearsWithMHPCO: 0 },
19	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
20	    });
21	
22	    // 100 base + 10 first insurance + 5 fee
23	    expect(result.results).toEqual([{ premium: 115 }]);
24	  });
25	  it("a single amulet → base premium 60 G", () => {
26	    const result = runScenario({
27	      customer: { yearsWithMHPCO: 0 },
28	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
29	    });
30	
31	    // 60 base + 6 first insurance + 5 fee
32	    expect(result.results).toEqual([{ premium: 71 }]);
33	  });
34	  it("a single staff → base premium 80 G", () => {
35	    const result = runScenario({
36	      customer: { yearsWithMHPCO: 0 },
37	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
38	    });
39	
40	    // 80 base + 8 first insurance + 5 fee
41	    expect(result.results).toEqual([{ premium: 93 }]);
42	  });
43	  it("a single potion → base premium 40 G", () => {
44	    const result = runScenario({
45	      customer: { yearsWithMHPCO: 0 },
46	      steps: [{ op: "quote", items: [{ type: "potion" }] }],
47	    });
48	
49	    // 40 base + 4 first insurance + 5 fee
50	    expect(result.results).toEqual([{ premium: 49 }]);
51	  });
52	  it.todo("a single rune (component) → base premium 25 G");
53	  it.todo("a single moonstone (component) → base premium 25 G");
54	
55	  // Building block of 3 alike components
56	  it.todo("2 runes → 50 G base premium");
57	  it.todo("3 runes → 60 G base premium (block applies)");
58	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
59	  it.todo("7 runes → 175 G base premium");
60	
61	  // "Alike" components means exactly the same type
62	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
63	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
64	
65	  // Item-specific modifiers
66	  it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
67	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
68	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
69	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");
70	
71	  // Policy-wide modifiers
72	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
73	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
74	  it.todo("first quote in a scenario → 10 % first insurance surcharge on the policy base");
75	  it.todo("second quote in a scenario → 15 % follow-up contract discount");
76	  it.todo("first insurance surcharge still applies on a follow-up contract");
77	
78	  // Modifier scope on multi-item policies
79	  it.todo(
80	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of the cursed item only) → 210 G before further modifiers and fee",
81	  );
82	
83	  // Rounding
84	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
85	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
86	
87	  // Integration examples
88	  it.todo(
89	    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
90	  );
91	  it.todo(
92	    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
93	  );
94	});
